--
-- LA MATIÈRE SPORT EST REFAITE EN CULTURE SPORTIVE (14/10/2026, Lucas :
-- « on va s'écarter du programme : l'histoire du sport, notamment de la France,
-- les fondamentaux — hypertrophie, force, endurance, récupération, anti-blessure »).
-- Les 8 fiches du programme officiel (champs d'apprentissage, rôles sociaux…),
-- identiques de la 6e à la 3e, n'intéressaient personne : rien à réviser pour un
-- écrit, et la langue de l'institution. Cadrage : docs/CADRAGE-SPORT.md.
-- Ce bloc installe 10 fiches sur Tle, et retire les
-- anciens chapitres de Sport de ce(s) niveau(x) (cascade : leçons, quiz,
-- questions, cahier, contrôles, déblocages).
--
-- Cette migration apporte : 10 chapitres, 10 leçons,
-- 10 quiz et 119 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [sport] Les anciens chapitres de Sport (Tle) partent — TOUS ceux dont
-- [sport] l'identifiant n'est pas dans ce bloc. Le ménage tourne AVANT les insertions ;
-- [sport] un rejeu ne touche donc jamais aux 10 fiches neuves (ni aux progrès des élèves
-- [sport] dessus). Les niveaux sont bornés à Tle : chaque bloc de la nouvelle
-- [sport] matière fait son propre ménage sur ses niveaux. La cascade (ON DELETE CASCADE
-- [sport] sur chapters) emporte leçons, quiz, questions, exercices, contrôles et
-- [sport] déblocages ; review_items n'a pas de clé étrangère et se vide à la main, et
-- [sport] les QUIZ se suppriment EXPLICITEMENT avant les chapitres : quizzes.lesson_id est en
-- [sport] ON DELETE SET NULL, pas en cascade — sans ce DELETE, les anciens quiz et leurs
-- [sport] questions resteraient orphelins et continueraient de nourrir Coach Turbo
-- [sport] (défaut trouvé au rejeu PGlite du 14/10/2026).
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'sport'
   AND c.level IN ('Tle')
   AND c.id NOT IN ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 'c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, '58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, '3e6141f6-e362-5765-a122-b8532787e93a'::uuid, '475d747d-a507-5860-ad09-00a4423612c4'::uuid, '3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, '0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, '7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, '8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 'f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid);

DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'sport'
   AND c.level IN ('Tle')
   AND c.id NOT IN ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 'c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, '58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, '3e6141f6-e362-5765-a122-b8532787e93a'::uuid, '475d747d-a507-5860-ad09-00a4423612c4'::uuid, '3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, '0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, '7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, '8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 'f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid);

DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'sport'
   AND c.level IN ('Tle')
   AND c.id NOT IN ('eb6d3920-c666-56aa-8d95-3c40ddf8b34f'::uuid, 'c8ffe450-41cc-5f3c-860d-ee330d92b067'::uuid, '58518308-9b83-5a9a-9ea1-7dd3909ab86b'::uuid, '3e6141f6-e362-5765-a122-b8532787e93a'::uuid, '475d747d-a507-5860-ad09-00a4423612c4'::uuid, '3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, '0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, '7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, '8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 'f16056b9-301c-5bcd-8db0-72e8c31a1dbb'::uuid);

