    ('475d747d-a507-5860-ad09-00a4423612c4'::uuid, 'Le sport dans la société'),
    ('3a645063-6988-5233-bf5f-1c89d6ccd46d'::uuid, 'Le sport dans la société'),
    ('0c7e3352-9d7e-5927-9560-c4de48d50b67'::uuid, 'Le sport dans la société'),
    ('7f3a9119-5afb-5151-889c-23f358b712dd'::uuid, 'Le sport dans la société'),
