-- 2. Leçons ----------------------------------------------------------------
INSERT INTO public.lessons (id, chapter_id, title, content, position) VALUES
  ('e8727ee9-6767-5efc-95c8-68e23f0a2e23', 'eb6d3920-c666-56aa-8d95-3c40ddf8b34f', 'Dessiner sa saison à rebours', E'Un nageur vise les championnats de France en avril. En septembre, il nage déjà beaucoup, sans jamais s’épuiser ; en mars, il nage moins, mais plus vite ; le jour J, il est frais. Rien de tout cela n’est un hasard : sa saison a été **dessinée à rebours**, de la date qui compte jusqu’à aujourd’hui.\n\n## Trois échelles de temps\nUn entraîneur découpe l’année comme un calendrier emboîté.\n\n| Cycle | Durée | Rôle |\n| **Macrocycle** | la saison entière | aller vers l’objectif principal |\n| **Mésocycle** | 3 à 6 semaines | développer une qualité (endurance, force, vitesse) |\n| **Microcycle** | la semaine | répartir les séances dures et les séances légères |\n\n## Les quatre périodes\nDans les années 1960, le Soviétique Lev Matveïev a décrit un schéma resté célèbre : la **périodisation**. Il découpe la saison en quatre périodes.\n\n| Période | Ce qu’on y fait |\n| **Préparation générale** | beaucoup de volume, des exercices variés, on bâtit le moteur |\n| **Préparation spécifique** | le travail se rapproche du sport pratiqué, l’intensité monte |\n| **Compétition** | on affûte, on vise les échéances, le volume baisse |\n| **Transition** | repos actif, on souffle et on se refait une santé |\n\n> Une saison réussie ne se résume pas à « s’entraîner plus » : elle organise le moment où l’on travaille dur et le moment où l’on récupère.\n\n## Charge et décharge\nLe corps progresse quand il encaisse une charge puis récupère. D’où la règle courante de **trois semaines dures pour une semaine légère** : la semaine de décharge laisse la surcompensation se faire. Sauter la décharge, c’est empiler de la fatigue sans la transformer en progrès.\n\n## L’affûtage : arriver frais le jour J\nAvant l’objectif, on lève le pied. L’**affûtage** dure **1 à 3 semaines** : on réduit le volume d’environ **40 à 60 %** tout en **gardant l’intensité**. Le corps efface la fatigue mais garde ses acquis. Garder l’intensité est essentiel : si l’on baisse tout, on perd la fraîcheur des gestes rapides.\n\n!> Un pic de forme ne se tient que **quelques semaines**. Personne ne peut être au sommet toute l’année : viser trois objectifs majeurs sur une saison, c’est souvent en rater deux.\n\n## Une autre manière : les blocs\nLe chercheur Vladimir Issurin a proposé la **périodisation par blocs** : plutôt que de tout travailler en même temps, on concentre l’entraînement sur une seule qualité à la fois pendant quelques semaines, puis on enchaîne.\n\n## Ta saison à toi : sport et bac\nTu n’as pas qu’un objectif sportif : tu as aussi un **calendrier scolaire**. Les épreuves du bac, les devoirs surveillés, les vacances pèsent sur ton sommeil et ton énergie. Un bon plan place les semaines les plus dures loin des périodes de révision intense, et prévoit une décharge au moment des examens.\n\n| Étape pour dessiner sa saison | Question à se poser |\n| 1. Fixer l’objectif | quelle est ma date clé ? |\n| 2. Remonter le temps | combien de semaines ai-je devant moi ? |\n| 3. Poser les repos | où mettre mes décharges et ma transition ? |\n| 4. Ajuster | mes examens tombent-ils en pleine charge ? |\n\n## À retenir\n- La saison se découpe en macrocycle, mésocycles et microcycles, avec quatre périodes : générale, spécifique, compétition, transition.\n- On alterne charge et décharge (environ trois semaines dures pour une légère) et on affûte 1 à 3 semaines avant l’objectif.\n- Un pic de forme dure quelques semaines : on dessine sa saison à rebours, en tenant compte du calendrier scolaire.', 1),
  ('bf63a50e-25f6-54e6-a922-5c8d539a5a6d', 'c8ffe450-41cc-5f3c-860d-ee330d92b067', 'Du chiffre à la décision', E'Une montre au poignet affiche 168 pulsations par minute. Bien ou mal ? Le chiffre seul ne dit rien : tout dépend de ta fréquence cardiaque maximale, de ton niveau de forme et de ce que tu veux travailler. **Mesurer**, c’est facile ; **interpréter**, c’est le vrai travail.\n\n## Les repères du cœur\n| Repère | Ce que c’est |\n| **FC de repos** | les battements par minute au calme, au réveil : elle baisse avec l’entraînement |\n| **FC max** | le maximum que ton cœur peut atteindre à l’effort |\n| **FC de réserve** | FC max − FC de repos : la marge dont tu disposes |\n\nPour viser une intensité, on utilise la **formule de Karvonen** : **FC cible = FC repos + % × (FC max − FC repos)**. Exemple : avec une FC de repos de 60 et une FC max de 200, viser 70 % donne 60 + 0,7 × 140 = **158**.\n\n## Les zones d’intensité\nOn range l’effort en cinq zones, de 1 (très facile, récupération) à 5 (maximal, quelques minutes au plus). Les zones basses construisent l’endurance, les hautes développent la puissance. Un piège fréquent : s’entraîner toujours « au milieu », ni assez facile pour récupérer, ni assez dur pour progresser.\n\n## Les tests de terrain\nLe laboratoire n’est pas nécessaire : des tests simples donnent une bonne idée de ta forme.\n\n| Test | Ce qu’il mesure |\n| **Navette 20 m de Léger** | l’endurance, en allers-retours de plus en plus rapides |\n| **VAMEVAL** | la vitesse maximale aérobie (VMA) sur piste |\n| **Léger-Boucher** | la VMA en courant par paliers |\n| **Cooper (12 min)** | la distance parcourue en 12 minutes, reflet de l’endurance |\n| **30-15 IFT** | la capacité à enchaîner des courses avec changements de direction |\n\nLa **VMA** est la vitesse à laquelle ton organisme consomme le plus d’oxygène : c’est la référence pour régler tes allures en course.\n\n## Mesurer le ressenti\nLes chiffres ne disent pas tout. L’**échelle de perception de l’effort de Borg** (RPE, de 1 à 10) demande simplement : « À quel point c’était dur ? » La **charge de séance** se calcule alors : **RPE × durée en minutes** (méthode de Foster). Une séance de 60 minutes à 7 donne 420 unités. En comparant la charge de la semaine en cours à celle des semaines précédentes (le **ratio aigu/chronique**), on repère les hausses trop brutales qui exposent à la blessure.\n\n> Mesurer, c’est relever des chiffres ; interpréter, c’est se demander ce qu’ils signifient pour la séance de demain.\n\n## Montres, capteurs et variabilité\nLes montres GPS et les capteurs cardiaques enregistrent distance, allure et pulsations. La **variabilité cardiaque** mesurée au réveil renseigne sur la fatigue du système nerveux. Ces outils aident, mais ils se trompent parfois : ils ne remplacent ni tes sensations, ni ton bon sens.\n\n## Le carnet d’entraînement\nLe carnet est l’outil le plus puissant, et il est gratuit. Tu y notes la date, la séance, la durée, le RPE, ton sommeil et ton humeur. C’est aussi ce que l’**AFL2** du bac d’EPS évalue : savoir s’entraîner, analyser et ajuster.\n\n!> Une semaine de carnet commentée vaut mieux que dix pages de chiffres sans réflexion : à chaque ligne, écris ce que tu changes la prochaine fois.\n\n## À retenir\n- On cible une intensité avec la FC de réserve (Karvonen) et on la situe dans une zone de 1 à 5.\n- Les tests de terrain (Léger, VAMEVAL, Cooper, 30-15 IFT) mesurent la forme ; le RPE multiplié par la durée donne la charge de séance.\n- Mesurer ne suffit pas : le carnet sert à interpréter les chiffres et à décider.', 1),
  ('027f9088-37e6-56d1-92bf-71f553301a56', '58518308-9b83-5a9a-9ea1-7dd3909ab86b', 'La minute avant le départ', E'Sur la ligne de départ, les mains sont moites, le cœur bat vite, les pensées s’emballent. Certains en font une arme, d’autres se paralysent. La différence n’est pas dans le corps : elle est dans la **préparation mentale**, qui s’apprend comme un geste technique.\n\n## Le stress n’est pas l’ennemi\nFace à un enjeu, le corps libère de l’**adrénaline** et du **cortisol** : le cœur accélère, la respiration s’emballe, les muscles se tendent. C’est une réponse normale, faite pour mobiliser. Le problème n’est pas d’être stressé, c’est de l’être **trop** ou **pas assez**.\n\n## La courbe en U inversé\nLa loi de **Yerkes-Dodson** dit que la performance monte avec l’activation, puis redescend quand elle est excessive.\n\n| Niveau d’activation | Effet sur la performance |\n| Trop bas | on est mou, on manque d’envie |\n| **Optimal** | concentration, énergie, précision |\n| Trop haut | tension, gestes crispés, erreurs |\n\n> L’objectif n’est pas de supprimer le stress, mais de trouver ton niveau d’activation optimal, qui varie selon le sport et la personne.\n\n## Se calmer par le souffle\nLa respiration est l’un des rares leviers directs sur le stress. La **cohérence cardiaque** consiste à respirer environ **6 fois par minute**, pendant **5 minutes** : inspirer 5 secondes, expirer 5 secondes. Elle apaise le rythme du cœur et aide à retrouver du calme avant l’effort.\n\n## Les routines et l’imagerie\nLes champions répètent les mêmes gestes avant l’action : c’est la **routine d’avant-performance**. Rafael Nadal, avant chaque service, enchaîne toujours les mêmes gestes avec sa raquette et ses vêtements. La routine ancre l’attention et évite de laisser les pensées vagabonder.\n\nL’**imagerie mentale** consiste à se voir réussir en pensée, en détail. Le nageur Michael Phelps visualisait ses courses du départ à l’arrivée, y compris les imprévus.\n\n## Fixer le bon objectif\nLes objectifs **SMART** sont Spécifiques, Mesurables, Atteignables, Réalistes et définis dans le Temps. Mieux encore : privilégier des objectifs de **processus** (« garder mon dos droit », « regarder ma cible ») plutôt que de **résultat** (« gagner »), car le processus dépend de toi, pas de l’adversaire.\n\n!> Le **dialogue interne** compte : « Je vais rater » installe l’échec, « Une action à la fois » aide à rester présent. On peut s’entraîner à choisir ses mots.\n\n## Craquer sous pression\nLe **choke**, c’est la contre-performance sous pression, quand on se met à surveiller son propre geste au lieu de lui faire confiance. Garder l’attention sur la cible et sur une consigne simple aide à l’éviter. La **concentration** est aussi une question d’attention : large pour lire le jeu, étroite pour exécuter un geste précis.\n\n## Le mental, c’est aussi la santé\nLa gymnaste **Simone Biles** s’est retirée de plusieurs finales aux Jeux de Tokyo en 2021 pour protéger sa santé mentale, ouvrant un large débat sur le bien-être des athlètes. Demander de l’aide est une force.\n\n## Ton Grand oral\nLe Grand oral est une performance : stress, souffle, routine, imagerie, objectif de processus. Les mêmes outils s’appliquent.\n\n## À retenir\n- Le stress est normal ; la performance est la meilleure à un niveau d’activation optimal (courbe en U inversé).\n- Souffle (cohérence cardiaque), routine, imagerie mentale et objectifs de processus se travaillent.\n- La santé mentale fait partie de la performance, et ces outils servent aussi au Grand oral.', 1),
  ('15c10cec-acfb-5966-ab1a-b3ccad645954', '3e6141f6-e362-5765-a122-b8532787e93a', 'Quand trop de sport fait reculer', E'Léo, 17 ans, s’entraîne six fois par semaine. En février, ses chronos stagnent ; en mars, ils reculent. Il dort mal, il est irritable, il enchaîne les rhumes. Il se dit qu’il n’en fait pas assez et ajoute une séance. C’est exactement le contraire de ce qu’il faudrait.\n\n## Trois états à distinguer\n| État | Durée de la fatigue | Que faire |\n| **Fatigue normale** | quelques heures à un jour | dormir, manger, reprendre |\n| **Surmenage** | quelques jours | alléger quelques jours |\n| **Surentraînement** | des semaines, voire des mois | arrêt ou forte baisse de charge, avis médical |\n\nLa fatigue normale est le signe d’un travail utile. Le surentraînement, lui, est un vrai déséquilibre.\n\n## Les signes d’alerte\n- une performance qui **baisse malgré le travail** ;\n- une **FC de repos élevée** au réveil ;\n- un sommeil perturbé ;\n- de l’irritabilité, de l’anxiété, une humeur plus sombre ;\n- des **infections à répétition** ;\n- une **perte d’appétit**.\n\n!> Un seul signe ne prouve rien, mais plusieurs ensemble doivent faire lever le pied et en parler à un médecin ou à un entraîneur.\n\n## Pourquoi ça arrive\nLe surentraînement vient d’un déséquilibre entre la charge et la récupération :\n- une charge qui **monte trop vite** ;\n- l’absence de **semaine de décharge** ;\n- un **manque de sommeil** ;\n- le **stress scolaire** et les examens, qui s’ajoutent à la fatigue sportive.\n\n> On progresse pendant la récupération, pas pendant l’effort : l’effort lance le signal, le repos fabrique le progrès.\n\n## Le meilleur remède : prévenir\nLa prévention repose sur la **planification** (décharges prévues, charge qui monte progressivement) et le **carnet** : si la FC de repos grimpe, que le sommeil se dégrade et que le RPE augmente à séance égale, on adapte avant de craquer.\n\n## Bien récupérer\n| Levier | Ce qu’il apporte |\n| **Sommeil** | le plus puissant : 9 h et plus pour un athlète adolescent |\n| **Nutrition** | glucides et protéines pour refaire les stocks |\n| **Récupération active** | marche, vélo léger, étirements doux |\n| **Massage, compression** | effet modeste, surtout du confort |\n| **Bain froid** | soulage, mais peut freiner la prise de muscle si on le fait systématiquement |\n\n## Le sommeil, champion de la récupération\nUne étude de l’université Stanford a fait dormir des basketteurs environ **10 heures par nuit** : leurs sprints et leurs lancers francs se sont améliorés. Dormir est un entraînement invisible.\n\n## Les écrans\nLa lumière des écrans le soir retarde l’endormissement. Poser le téléphone une heure avant de dormir aide à gagner en profondeur de sommeil, donc en récupération.\n\n## Le journal d’un sportif qui en fait trop\nImagine-toi relire le carnet de Léo : FC de repos passée de 55 à 65 en trois semaines, sommeil de six heures, RPE à 9 pour des séances habituellement à 6. Les chiffres racontaient l’histoire avant qu’il ne la sente. Le carnet est un lanceur d’alerte.\n\n## À retenir\n- Fatigue normale, surmenage, surentraînement : la durée et les signes changent la réaction à avoir.\n- Le surentraînement vient d’un déséquilibre entre charge et récupération ; le carnet et la planification le préviennent.\n- Le sommeil est le premier outil de récupération, devant massages et bains froids.', 1),
  ('2ba4440f-d953-5fe4-80ec-bf3fd0eab093', '475d747d-a507-5860-ad09-00a4423612c4', 'Un chiffre, une ordonnance', E'Voici un chiffre qui devrait t’arrêter : selon l’ANSES, en 2020, **deux tiers des 11-17 ans** présentent en France un risque sanitaire préoccupant, par trop d’écrans et pas assez d’activité physique. Le sport n’est pas qu’un loisir : c’est aussi une question de **santé publique**.\n\n## Ce que recommande l’OMS\nL’Organisation mondiale de la santé fixe des repères simples.\n\n| Public | Recommandation |\n| Enfants et jeunes de 5 à 17 ans | **60 minutes par jour** d’activité modérée à soutenue |\n| Adultes | **150 à 300 minutes par semaine** d’activité modérée |\n\n> Bouger un peu vaut mieux que ne pas bouger du tout, et bouger plus apporte encore davantage.\n\n## Sédentarité et inactivité : deux problèmes distincts\nOn confond souvent les deux.\n- L’**inactivité physique**, c’est ne pas atteindre les niveaux d’activité recommandés.\n- La **sédentarité**, c’est le **temps passé assis ou allongé** en étant éveillé : devant un écran, en classe, dans les transports.\n\nOn peut faire une heure de sport et rester sédentaire le reste de la journée : **les deux comptent**. L’OMS range l’inactivité physique parmi les **premiers facteurs de risque de mortalité** dans le monde.\n\n## Des bénéfices à tous les âges\n| Domaine | Ce que le sport change |\n| Cœur et vaisseaux | tension plus basse, cœur plus efficace |\n| Poids | moins de risque de surpoids |\n| Diabète | meilleur contrôle du sucre dans le sang |\n| Santé mentale | moins d’anxiété et de symptômes dépressifs |\n| Sommeil | endormissement plus facile et sommeil plus profond |\n\n## Le sport sur ordonnance\nEt si ton médecin te prescrivait… du sport ? C’est possible. La **loi de 2016**, en vigueur depuis **2017**, permet à un médecin de prescrire de l’**activité physique adaptée** aux personnes atteintes d’une maladie de longue durée. Le dispositif a été **élargi en 2022**. L’activité est adaptée à l’état de santé de chacun, encadrée par des professionnels.\n\nLes **Maisons Sport-Santé**, créées à partir de **2019**, accueillent ceux qui veulent se remettre au sport avec un accompagnement : on y est orienté, conseillé et suivi.\n\n!> « Adaptée » ne veut pas dire « allégée pour rien » : la séance est dosée pour que la personne progresse sans se mettre en danger.\n\n## Et à l’école ?\nL’État a lancé en **2022** les **30 minutes d’activité physique quotidienne** à l’école primaire. L’activité physique a aussi été déclarée **grande cause nationale en 2024**, année des Jeux de Paris. L’idée : faire du mouvement un réflexe, pas une corvée.\n\n## Un chiffre, une action\nSi tu passes huit heures par jour assis entre cours, transports et écrans, tes 60 minutes d’activité n’effacent pas tout. Pour réduire la sédentarité : te lever à chaque pause, marcher pour tes trajets, couper le téléphone plus tôt le soir.\n\n## À retenir\n- L’OMS recommande 60 minutes par jour de 5 à 17 ans et 150 à 300 minutes par semaine chez l’adulte.\n- Sédentarité (temps assis) et inactivité (pas assez d’activité) sont deux risques distincts, tous deux nocifs.\n- Sport sur ordonnance (loi de 2016, élargi en 2022) et Maisons Sport-Santé (2019) mettent le sport au service de la santé.', 1),
  ('9f26e9ab-4968-50b3-bc94-a35f599ae9d6', '3a645063-6988-5233-bf5f-1c89d6ccd46d', 'Le stade comme miroir', E'Un soir de match, un stade entier chante le même hymne. Quelques rangs plus haut, des supporters brandissent des écharpes. Dehors, des familles regardent l’écran. Le sport n’est pas seulement un geste : c’est un **miroir de la société**, avec ses fiertés, ses inégalités, ses tensions.\n\n## Le sport comme institution\nLes sociologues étudient le sport comme une **institution** (avec ses règles, ses fédérations), une **économie** (billetterie, droits télé, équipementiers) et un **discours** (les valeurs qu’on lui attribue : effort, mérite, dépassement).\n\n## Elias : canaliser la violence\nLe sociologue **Norbert Elias** a décrit un « **processus de civilisation** » : au fil des siècles, la violence a été peu à peu contrôlée. Le sport en est une illustration. Un match de rugby est violent, mais **réglementé**, encadré par un arbitre : on se bat sans se blesser gravement. Le sport canalise la violence.\n\n## Bourdieu : des sports de classes ?\nEn **1978**, **Pierre Bourdieu** a montré que les pratiques sportives se distribuent selon les **classes sociales**.\n\n| Plutôt lié aux classes aisées | Plutôt lié aux classes populaires |\n| golf, tennis, équitation | boxe, football |\n\nLe choix d’un sport dit quelque chose du milieu : coût, lieux de pratique, codes. Cette lecture est ancienne et discutée : les pratiques ont évolué, mais elle donne une grille pour comprendre.\n\n## Identité et nation\nLe sport fabrique du **collectif**. Les **hymnes** chantés avant le coup d’envoi, le **haka** des All Blacks néo-zélandais, les **deux étoiles** sur le maillot des Bleus après les titres de champion du monde (1998 et 2018) : ce sont des signes d’appartenance.\n\n## Supporters et violence\nLes supporters donnent au sport son ambiance. Les **ultras** organisent chants et animations ; une minorité dérape. Deux drames ont marqué l’histoire : le **Heysel** (**1985**, Belgique) et **Hillsborough** (**1989**, Angleterre), qui ont conduit à renforcer la sécurité dans les stades.\n\n> Le stade est un espace où la société se montre telle qu’elle est : solidaire, fière, mais aussi inégale et parfois violente.\n\n## Inclusion : handisport et égalité\nLes **Jeux paralympiques** sont nés de la compétition de **Stoke Mandeville** en **1948**, pour des blessés de guerre, et la première édition officielle a eu lieu à **Rome en 1960**. Le sport peut aussi faire progresser l’égalité entre femmes et hommes, même si les femmes ont longtemps été exclues de nombreuses disciplines.\n\n!> En 2023-2024, le port du **hijab** en compétition a nourri un débat sur la **laïcité** et l’égalité d’accès au sport, avec des positions différentes selon les fédérations et les institutions.\n\n## L’olympisme, idéal et vitrine\nL’idéal olympique parle de paix et de fraternité ; les Jeux sont aussi une **vitrine** politique et économique. Le **dopage** apparaît alors comme un symptôme de la pression à gagner.\n\n## Sport et environnement\nFabriquer de la **neige artificielle** pour les stations, multiplier les **déplacements** pour les compétitions : le sport laisse une empreinte écologique, et pose la question de son avenir.\n\n## À retenir\n- Le sport est une institution, une économie et un discours : il reflète la société.\n- Elias y voit la violence canalisée, Bourdieu des pratiques liées aux classes sociales (1978).\n- Identité, supporters, inclusion paralympique, laïcité et environnement montrent un sport au cœur des débats.', 1),
  ('046b58a1-2918-5d4f-b17e-cf5439cc1bf9', '0c7e3352-9d7e-5927-9560-c4de48d50b67', 'Qu’est-ce qui reste quand la flamme s’éteint ?', E'Le 26 juillet 2024, la cérémonie d’ouverture des Jeux de Paris ne se tient pas dans un stade, mais sur la Seine. Quelques semaines plus tard, la flamme s’éteint. Mais que reste-t-il d’un tel événement ? C’est la grande question de l’**héritage olympique**.\n\n## La Charte et les valeurs\nLa **Charte olympique** est le texte qui fixe les principes du mouvement olympique. Trois valeurs en forment le cœur.\n\n| Valeur | Ce qu’elle dit |\n| **Excellence** | donner le meilleur de soi, pas seulement gagner |\n| **Amitié** | rapprocher des peuples par le sport |\n| **Respect** | respecter les règles, les adversaires, soi-même |\n\nLa **trêve olympique**, appuyée par une résolution de l’ONU, appelle à suspendre les conflits pendant les Jeux. Son application reste incertaine, mais l’idée est puissante.\n\n## L’Agenda 2020 : des Jeux moins chers\nFace à des Jeux de plus en plus coûteux, le CIO a adopté l’**Agenda 2020** : des Jeux **moins chers**, qui **réutilisent des sites existants** plutôt que de tout construire.\n\n## Paris 2024 en chiffres\n| Donnée | Valeur |\n| Sites existants ou temporaires | environ **95 %** |\n| Athlètes | environ **10 500** |\n| Parité | autant de places pour les femmes que pour les hommes |\n| Billetterie paralympique | un **record** de ventes |\n\n> Un bon héritage se prépare avant les Jeux : on ne construit que ce dont on se servira ensuite.\n\n## L’héritage concret\n- **La Seine** : après de gros travaux, la baignade y est de nouveau possible, rendue au public en **2025**.\n- **Le village olympique** : devenu un **quartier de logements** à Saint-Denis, Saint-Ouen et L’Île-Saint-Denis.\n- **Le centre aquatique de Saint-Denis**, ouvert aux habitants et aux clubs.\n- Des **piscines** de quartier créées ou rénovées.\n\n## Les controverses\nUn événement de cette taille suscite aussi des critiques.\n- Le **coût** et la question de qui paie.\n- Les mesures de **sécurité**, très lourdes.\n- Les **délogements** de personnes vivant en précarité signalés avant les Jeux.\n\n!> Savoir citer les bénéfices ET les critiques est la marque d’une réflexion solide, au bac comme au Grand oral.\n\n## La suite\nAprès Paris, les prochains rendez-vous sont **Milan-Cortina 2026** (Jeux d’hiver), **Los Angeles 2028** et les **Alpes françaises 2030** (Jeux d’hiver). Chaque ville devra faire sa propre réponse à la question de l’héritage.\n\n## Ton avis compte\nSi tu devais juger les Jeux de Paris, quels critères retiendrais-tu ? Le coût, les valeurs, les équipements laissés aux habitants, l’image du pays ? Aucune réponse n’est unique, mais chacune doit s’appuyer sur des faits.\n\n## À retenir\n- Les trois valeurs olympiques sont l’excellence, l’amitié et le respect ; la trêve olympique appelle à suspendre les conflits.\n- Paris 2024 : environ 95 % de sites existants ou temporaires, environ 10 500 athlètes, la parité et un record de billetterie paralympique.\n- L’héritage (Seine, village, centre aquatique, piscines) s’accompagne de controverses sur le coût, la sécurité et les délogements.', 1),
  ('22d5137f-ea41-5d5a-a9a6-9a57fb774b2e', '7f3a9119-5afb-5151-889c-23f358b712dd', 'Cinq portraits de métiers', E'Inès veut vivre du sport sans forcément être championne. Elle hésite entre professeure d’EPS, préparatrice physique et organisatrice d’événements. Bonne nouvelle : le sport, c’est aussi un **vaste secteur d’emploi**. Il suffit de trouver la bonne porte.\n\n## STAPS : la grande filière\n**STAPS** signifie sciences et techniques des activités physiques et sportives. La licence STAPS se décline en **cinq mentions** :\n\n| Mention | Pour quoi faire |\n| **Entraînement sportif** | devenir entraîneur, préparateur physique |\n| **Activité physique adaptée et santé** | accompagner des personnes malades, âgées, handicapées |\n| **Éducation et motricité** | enseigner, former |\n| **Management du sport** | gérer clubs, événements, structures |\n| **Ergonomie du sport et performance motrice** | analyser le geste, concevoir le matériel |\n\nSur Parcoursup, les attentes portent sur trois champs : les **sciences** (biologie, physique), l’**expression** (écrit, oral) et la **pratique** sportive. Il ne suffit donc pas d’être sportif.\n\n## Portrait 1 : professeur d’EPS\nOn passe par un **master MEEF**, puis on prépare le **CAPEPS**, le concours qui mène au métier.\n\n## Portrait 2 : entraîneur\nLe ministère des Sports délivre des diplômes : le **BPJEPS**, le **DEJEPS** et le **DESJEPS**, de plus en plus élevés, pour animer, entraîner et diriger.\n\n## Portrait 3 : kinésithérapeute\nSoigner et rééduquer. L’accès passe par différentes voies selon les universités (**PASS**, **LAS**, ou une première année de STAPS dans certains cas) : il faut vérifier auprès de l’établissement visé.\n\n> Chaque métier a son diplôme : commence par le métier qui t’attire, puis remonte vers la formation.\n\n## Portrait 4 : préparateur physique et analyste de données\nLe **préparateur physique** construit la condition physique des sportifs. L’**analyste de données** exploite les chiffres (GPS, capteurs, statistiques) pour éclairer les décisions de l’entraîneur : un métier qui monte.\n\n## Portrait 5 : organisateur d’événements, journaliste, industrie\n- **Organisateur d’événements** : coordonne logistique, sécurité, communication.\n- **Journaliste sportif** : raconte, analyse, filme.\n- **Industrie** : les équipementiers conçoivent chaussures, maillots, matériel.\n\n## Sportif de haut niveau : un statut, des aménagements\nUn jeune sportif de haut niveau peut bénéficier d’**aménagements scolaires** (horaires, examens, soutien) pour concilier études et entraînements. Les pôles et sections permettent de ne pas sacrifier l’un à l’autre.\n\n## Un secteur qui emploie\nLe sport représente en France **plusieurs centaines de milliers d’emplois** : enseignement, clubs, salles de sport, événementiel, industrie, médias.\n\n!> Beaucoup de métiers exigent un diplôme précis : vérifie toujours les conditions d’accès sur le site officiel de la formation avant de te décider.\n\n## Choisir pour toi\nPose-toi trois questions : qu’est-ce que j’aime faire ? avec qui ? dans quel cadre (terrain, bureau, hôpital) ? Les réponses orienteront ta formation.\n\n## À retenir\n- La licence STAPS compte cinq mentions et attend des sciences, de l’expression et de la pratique.\n- Professeur d’EPS (master MEEF et CAPEPS), entraîneur (BPJEPS, DEJEPS, DESJEPS), préparateur, analyste, organisateur… : les portes sont nombreuses.\n- Les sportifs de haut niveau bénéficient d’aménagements scolaires ; le secteur emploie plusieurs centaines de milliers de personnes.', 1),
  ('a26d2a62-b297-5a4e-871b-d8c9299b5113', '8561efa6-7303-530e-a51d-a4b84b1ef822', 'Trois épreuves, trois champs, une moyenne', E'L’EPS compte au baccalauréat, et elle se joue presque entièrement pendant l’année de Terminale. Connaître les règles, c’est savoir où sont les points — et quels choix tu peux faire.\n\n## Le cadre\nLes règles sont fixées par la note de service du 20 février 2026 (BO n° 9 du 26 février 2026), applicable dès la session 2026 ; les référentiels nationaux d’évaluation, eux, n’ont pas changé.\n\n| Élément | Ce qu’il faut savoir |\n| Mode d’évaluation | Le **contrôle en cours de formation** (CCF), pendant l’année de Terminale, pour les élèves des lycées publics et privés sous contrat |\n| Nombre d’épreuves | **Trois**, sur trois activités distinctes |\n| Champs | Trois **champs d’apprentissage différents** |\n| Activités | Au moins **deux** issues de la liste nationale ; la troisième peut venir de la liste académique ou d’une activité propre à l’établissement |\n| Notation | Chaque épreuve est notée sur 20 ; la note finale est la **moyenne des trois**, arrondie au point entier après harmonisation |\n| Évaluateurs | Deux enseignants d’EPS de l’établissement (**co-évaluation**), dont celui de la classe |\n| Coefficient | **6** au baccalauréat |\n\n## Une épreuve, trois attendus\n| Attendu | Points | Quand il est évalué |\n| **AFL1** : agir, performer, être efficace | **12** | Le jour de l’épreuve |\n| **AFL2** : s’entraîner, se préparer, analyser | 8 points partagés avec l’AFL3 | Au fil de la séquence, finalisé le jour de l’épreuve |\n| **AFL3** : tenir des rôles | (partagés avec l’AFL2) | Au fil de la séquence, finalisé le jour de l’épreuve |\n\nPour les AFL2 et AFL3, **tu choisis la répartition** des 8 points :\n\n| Choix | AFL2 | AFL3 |\n| Équilibré | 4 | 4 |\n| Priorité à l’entraînement | 6 | 2 |\n| Priorité aux rôles | 2 | 6 |\n\n> L’AFL2 et l’AFL3 se gagnent **pendant la séquence**, pas le jour de l’épreuve seulement : un carnet tenu régulièrement et un rôle assumé à chaque séance valent des points.\n\n## Les règles qui piègent\n!> Une absence **non justifiée** à une épreuve vaut **0** à cette épreuve (non éliminatoire, mais il fait chuter la moyenne).\n\n- Une blessure ou un problème de santé temporaire, attesté, ouvre droit à une **épreuve adaptée ou différée**.\n- L’évaluation ne peut jamais reposer sur les seuls AFL2 et AFL3, même en cas d’inaptitude partielle : il y a toujours une part d’action motrice, adaptée si besoin.\n- Les candidats individuels et ceux du Cned passent un **examen ponctuel terminal**, sur deux activités.\n\n## Et au-delà de l’enseignement commun\nCertains lycées proposent un **enseignement optionnel d’EPS**, qui approfondit la pratique et la réflexion sur les activités, et la spécialité **« Éducation physique, pratiques et culture sportives »** (EPPCS), qui a ses propres épreuves. Renseigne-toi auprès de ton lycée : l’offre varie d’un établissement à l’autre.\n\n## Exemple de calcul\nUn élève obtient 14/20 en demi-fond (CA1), 16/20 en acrosport (CA3) et 12/20 en badminton (CA4).\n- Moyenne : (14 + 16 + 12) / 3 = **14/20**.\n- En badminton, il avait choisi 6 points pour l’AFL3 (arbitrage) et 2 pour l’AFL2 : son arbitrage régulier tout au long de la séquence a limité l’effet d’une rencontre ratée le jour de l’épreuve.', 1),
  ('b66aa652-5354-5d9e-8e8e-367245c2e948', 'f16056b9-301c-5bcd-8db0-72e8c31a1dbb', 'Est-ce pour moi ?', E'Tu aimes le sport, mais pas seulement pour y jouer : tu voudrais comprendre comment le corps s’entraîne, pourquoi le sport fascine, ce qu’il dit de la société. Le lycée t’offre justement deux chemins pour aller plus loin que l’EPS commune : l’**option EPS** et la **spécialité EPPCS**. Reste à savoir lequel te convient.\n\n## L’option EPS : plus de pratique, plus de réflexion\nL’**enseignement optionnel d’EPS** s’étend de la 2de à la Tle, à raison de **3 heures par semaine**, selon un programme de **2019**. Son but : **approfondir la pratique** et **réfléchir sur le sport**. Elle compte en **contrôle continu**.\n\n| Élément | Option EPS |\n| Durée | de la 2de à la Tle |\n| Horaire | 3 heures par semaine |\n| Ce qu’on y fait | pratiquer davantage et réfléchir sur le sport |\n| Évaluation | contrôle continu |\n\n## La spécialité EPPCS : une vraie matière de culture sportive\nLa spécialité **« Éducation physique, pratiques et culture sportives »**, ou **EPPCS**, a été créée en **2021**. C’est une spécialité à part entière, qu’on choisit en 1re parmi les autres.\n\n| Élément | EPPCS |\n| Horaire en 1re | 4 heures par semaine |\n| Horaire en Tle | 6 heures par semaine |\n| Épreuve terminale | un écrit et une partie pratique |\n\n> L’option approfondit ta pratique ; la spécialité en fait une discipline de culture, avec des sciences, de l’histoire, de la sociologie et des projets.\n\n## Ce qu’on y apprend\nEn EPPCS, on étudie :\n- les **sciences du sport** : physiologie, entraînement, biomécanique ;\n- l’**histoire** du sport et de ses grandes évolutions ;\n- la **sociologie** : le sport dans la société, les inégalités, les identités ;\n- un **projet collectif** qui mêle pratique et réflexion.\n\nTu retrouves, en plus structuré, une grande partie de ce que ces fiches abordent : périodisation, récupération, olympisme, santé publique.\n\n## Pour qui ?\nL’EPPCS s’adresse à celles et ceux qui aiment **à la fois** pratiquer et réfléchir, et qui visent souvent des études comme **STAPS**, kinésithérapie, éducation, management du sport. Ce n’est pas un cours de sport en plus : il y a de l’**écrit**, des notions à maîtriser.\n\n!> Choisir EPPCS, c’est accepter de travailler comme dans une matière théorique : prends le temps de consulter le programme officiel et de demander conseil à tes professeurs d’EPS.\n\n## Les structures autour du sport au lycée\n- Les **sections sportives scolaires** permettent de s’entraîner davantage pendant les heures de classe.\n- Les **pôles espoirs** accueillent des jeunes à fort potentiel.\n- Le **sport-études** organise une scolarité adaptée aux entraînements.\n- Les **aménagements pour sportif de haut niveau** (horaires, examens) existent pour concilier études et carrière.\n\n## Et le Grand oral ?\nAvec l’EPPCS, tu peux choisir une spécialité sportive comme point d’appui pour ton **Grand oral** : un sujet sur la récupération, l’olympisme ou la santé publique devient un terrain naturel.\n\n## Se poser les bonnes questions\nAimes-tu écrire autant que courir ? Veux-tu travailler en projet avec d’autres ? Vises-tu des études liées au sport ? Si tu réponds oui, l’EPPCS mérite ton attention. Sinon, l’option EPS ou la seule EPS commune peuvent déjà t’apporter beaucoup.\n\n## À retenir\n- L’option EPS (3 h par semaine de la 2de à la Tle, programme 2019) approfondit la pratique et la réflexion, et compte en contrôle continu.\n- La spécialité EPPCS (créée en 2021, 4 h en 1re, 6 h en Tle) associe sciences du sport, histoire, sociologie et projet, avec écrit et pratique.\n- Sections sportives, pôles espoirs, sport-études et aménagements aident à concilier études et haut niveau.', 1)
ON CONFLICT DO NOTHING;

-- 3. Quiz ------------------------------------------------------------------
-- Double garde : ON CONFLICT (id) protège du rejeu, et le NOT EXISTS protège
-- la leçon d’un SECOND quiz venu d’ailleurs — le hub de leçon lit son quiz en
-- .maybeSingle(), deux quiz feraient lever « multiple rows » à de vrais élèves.
INSERT INTO public.quizzes (id, title, subject, grade_level, chapter, is_free, lesson_id)
SELECT v.id, v.title, v.subject, v.grade_level, v.chapter, true, l.id
  FROM (VALUES
    ('f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Quiz — Dessiner sa saison à rebours', 'Sport', 'Tle', 'Planifier une saison : périodisation et pic de forme', 'e8727ee9-6767-5efc-95c8-68e23f0a2e23'::uuid),
    ('f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Quiz — Du chiffre à la décision', 'Sport', 'Tle', 'Mesurer et analyser : fréquence cardiaque, VMA, tests et carnet', 'bf63a50e-25f6-54e6-a922-5c8d539a5a6d'::uuid),
    ('97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Quiz — La minute avant le départ', 'Sport', 'Tle', 'Le mental : stress, concentration, routines', '027f9088-37e6-56d1-92bf-71f553301a56'::uuid),
    ('b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Quiz — Quand trop de sport fait reculer', 'Sport', 'Tle', 'Surentraînement et récupération', '15c10cec-acfb-5966-ab1a-b3ccad645954'::uuid),
    ('0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Quiz — Un chiffre, une ordonnance', 'Sport', 'Tle', 'Sport et santé publique : sédentarité et sport sur ordonnance', '2ba4440f-d953-5fe4-80ec-bf3fd0eab093'::uuid),
    ('4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Quiz — Le stade comme miroir', 'Sport', 'Tle', 'Le sport comme fait social', '9f26e9ab-4968-50b3-bc94-a35f599ae9d6'::uuid),
    ('95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Quiz — Qu’est-ce qui reste quand la flamme s’éteint ?', 'Sport', 'Tle', 'L’olympisme : valeurs, Paris 2024 et l’héritage', '046b58a1-2918-5d4f-b17e-cf5439cc1bf9'::uuid),
    ('887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Quiz — Cinq portraits de métiers', 'Sport', 'Tle', 'Les métiers du sport et la filière STAPS', '22d5137f-ea41-5d5a-a9a6-9a57fb774b2e'::uuid),
    ('9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Quiz — Trois épreuves, trois champs, une moyenne', 'Sport', 'Tle', 'Le bac d’EPS : épreuves, AFL et barème', 'a26d2a62-b297-5a4e-871b-d8c9299b5113'::uuid),
    ('29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Quiz — Est-ce pour moi ?', 'Sport', 'Tle', 'L’option EPS et la spécialité EPPCS', 'b66aa652-5354-5d9e-8e8e-367245c2e948'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('60296acd-2a96-5337-b6e2-0ef126ea3abc'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Comment appelle-t-on la saison entière dans le découpage d’un entraîneur ?', 'mcq', '["Le macrocycle","Le mésocycle","Le microcycle","La transition"]'::jsonb, 0, 'Le macrocycle est le grand cycle de la saison ; le mésocycle dure 3 à 6 semaines et le microcycle une semaine.', 1),
    ('0c380aca-6884-5bb5-b7d3-a8a5ac5305d5'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Combien de temps dure en général un mésocycle ?', 'mcq', '["De 3 à 6 semaines","Un seul jour","Un an et demi","Dix minutes"]'::jsonb, 0, 'Le mésocycle, de 3 à 6 semaines, sert à développer une qualité précise comme l’endurance ou la force.', 2),
    ('f4f5df0a-29ef-580a-be0e-0ae3b62f5c6b'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Quelle période de la saison vise surtout à bâtir le moteur avec beaucoup de volume ?', 'mcq', '["La préparation générale","La compétition","La transition","L’affûtage"]'::jsonb, 0, 'C’est en préparation générale qu’on accumule du volume et des exercices variés avant de se rapprocher du sport pratiqué.', 3),
    ('be9d18a7-0474-587b-8421-7fbf066be50b'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Que fait-on pendant la période de transition ?', 'mcq', '["On se repose activement et on récupère","On s’entraîne au maximum","On passe tous les tests","On change de sport définitivement"]'::jsonb, 0, 'La transition suit la saison : repos actif pour se refaire une santé avant de repartir.', 4),
    ('4c0cb8f7-906a-5f83-b6fb-dd63ac406f65'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Qu’est-ce que la surcompensation permet dans la règle des « trois semaines dures, une légère » ?', 'mcq', '["Transformer la fatigue en progrès pendant la semaine de décharge","Gagner plus de poids","Éviter tout repos","Supprimer les courbatures à vie"]'::jsonb, 0, 'La semaine légère laisse le corps réparer et dépasser son niveau de départ ; sans elle, la fatigue s’empile.', 5),
    ('40665704-ee5f-5aa4-bf78-a29d122fdff1'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Pendant l’affûtage, que fait-on du volume et de l’intensité ?', 'mcq', '["On baisse le volume en gardant l’intensité","On baisse les deux au maximum","On monte le volume et on baisse l’intensité","On ne change rien"]'::jsonb, 0, 'On réduit le volume de 40 à 60 % mais on garde l’intensité : le corps se rafraîchit sans perdre ses acquis.', 6),
    ('655999a5-7f5f-50ce-975c-3db62bc8b16f'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'L’affûtage dure en général plusieurs mois avant la compétition.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il dure 1 à 3 semaines : bien plus long, on perdrait le bénéfice de l’entraînement.', 7),
    ('099cfcce-51f9-5ab3-91f4-71e2fa005c7e'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Un sportif peut rester à son pic de forme toute l’année.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un pic de forme ne se tient que quelques semaines : il faut le viser pour les objectifs principaux.', 8),
    ('83da7b77-7957-5b58-8581-186652d6ab64'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'À quelle époque Matveïev a-t-il décrit sa périodisation ?', 'mcq', '["Dans les années 1960","Au XIXe siècle","En 2010","Dans les années 1920"]'::jsonb, 0, 'Lev Matveïev a proposé son schéma en quatre périodes dans les années 1960.', 9),
    ('6f2aa45e-d899-5e94-a209-e9aca5cb2bea'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Que propose la périodisation par blocs défendue par Vladimir Issurin ?', 'mcq', '["Concentrer l’entraînement sur une qualité à la fois pendant quelques semaines","Travailler toutes les qualités chaque jour","Supprimer les semaines de repos","S’entraîner seulement avant l’objectif"]'::jsonb, 0, 'Plutôt que de tout mélanger, on met un bloc d’entraînement sur une seule qualité, puis on passe à la suivante.', 10),
    ('23506ee1-50f4-5c25-a3d4-ebe2927ebff8'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Pourquoi tenir compte du calendrier du bac dans sa saison sportive ?', 'mcq', '["Parce que les examens pèsent sur le sommeil et l’énergie","Parce que le bac impose des séances","Parce que la fatigue disparaît pendant les révisions","Parce que les entraîneurs l’exigent"]'::jsonb, 0, 'Les semaines dures doivent éviter les périodes de révision intense, et une décharge se place au moment des examens.', 11),
    ('3c0247ab-d549-5922-8338-9f30eb35f90b'::uuid, 'f030b19d-1304-5e4d-a730-a96a2d081312'::uuid, 'Par quoi commence-t-on pour dessiner sa saison ?', 'mcq', '["Par la date de l’objectif principal, puis on remonte le temps","Par la dernière séance de l’année","Par l’achat du matériel","Par le choix de la tenue"]'::jsonb, 0, 'On fixe la date clé, on compte les semaines disponibles, puis on place les repos : la saison se dessine à rebours.', 12),
    ('bd9b8d71-11aa-5a77-91be-e3d8558351ba'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Que désigne la fréquence cardiaque de réserve ?', 'mcq', '["La différence entre la FC max et la FC de repos","La FC au réveil","La FC moyenne d’un match","Le total des battements dans une journée"]'::jsonb, 0, 'FC de réserve = FC max − FC de repos : c’est la marge de travail du cœur.', 1),
    ('0457a91b-cc52-561c-bea0-0694d63d6a1e'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Avec une FC de repos de 60, une FC max de 200 et une cible à 70 %, quelle est la FC cible selon Karvonen ?', 'mcq', '["158","140","170","130"]'::jsonb, 0, '60 + 0,7 × (200 − 60) = 60 + 98 = 158.', 2),
    ('4c4751a8-44e6-5681-be02-a10261166e8e'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Que mesure surtout le test de Cooper ?', 'mcq', '["La distance parcourue en 12 minutes","La force maximale","La souplesse","La précision de tir"]'::jsonb, 0, 'Le test de Cooper compte la distance faite en 12 minutes, reflet de l’endurance.', 3),
    ('4ce9a70f-a1cf-517b-a799-a44a461096e8'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Quel test enchaîne des courses avec changements de direction ?', 'mcq', '["Le 30-15 IFT","Le test de Cooper","Le test de la chandelle","Le saut en longueur"]'::jsonb, 0, 'Le 30-15 IFT évalue la capacité à répéter des courses avec changements de direction.', 4),
    ('06a4c479-b660-5019-a769-9aef9f0f71bd'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Que signifie VMA ?', 'mcq', '["Vitesse maximale aérobie","Volume moyen d’allure","Variation musculaire active","Vitesse maximale absolue"]'::jsonb, 0, 'La VMA est la vitesse à laquelle l’organisme consomme le plus d’oxygène ; elle sert à régler les allures.', 5),
    ('5086da1f-85fe-55ec-be1d-099fa9e18742'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Comment calcule-t-on la charge d’une séance selon Foster ?', 'mcq', '["RPE × durée de la séance","FC max × durée","Distance ÷ temps","Poids × répétitions"]'::jsonb, 0, 'On multiplie la perception de l’effort (RPE) par la durée en minutes : 60 min à 7 donnent 420.', 6),
    ('77cdc641-4064-5ce5-8950-9565f0772906'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'L’échelle de Borg (RPE) va de 1 à 10 et mesure le ressenti de l’effort.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle demande simplement à quel point la séance a été dure, de 1 (très facile) à 10 (maximal).', 7),
    ('43a6c978-703e-5d29-87ed-e9d106fdda72'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Un ratio aigu/chronique très élevé signale…', 'mcq', '["une hausse brutale de charge qui expose à la blessure","un excellent état de forme","une séance trop facile","un manque de sommeil uniquement"]'::jsonb, 0, 'Comparer la charge de la semaine à celle des semaines précédentes permet de repérer les montées trop rapides.', 8),
    ('ceb33c6b-8e16-52e3-ad4d-92fbfaffb376'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Mesurer et interpréter, c’est la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Mesurer, c’est relever des chiffres ; interpréter, c’est comprendre ce qu’ils signifient et décider de la suite.', 9),
    ('0cb23dd7-97c9-5aa9-9c37-6ee6c12e3211'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Que peut-on noter dans un carnet d’entraînement ?', 'mcq', '["La séance, la durée, le RPE, le sommeil et l’humeur","Uniquement le score des matchs","Seulement le poids soulevé","Rien : il vaut mieux se fier à sa mémoire"]'::jsonb, 0, 'Plus le carnet est complet, plus on peut analyser et ajuster ses séances.', 10),
    ('2ffafe1e-fa29-5bb7-b14b-e2364b16104e'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'Quel attendu du bac d’EPS évalue notamment le carnet d’entraînement ?', 'mcq', '["L’AFL2","L’AFL1","Aucun","L’AFL4"]'::jsonb, 0, 'L’AFL2 évalue la capacité à s’entraîner, à analyser et à ajuster, le carnet en étant la trace.', 11),
    ('2d10fefc-d4e2-56db-9008-ca668df6c4a5'::uuid, 'f0f90da3-618c-524b-99b6-f1043948dcbb'::uuid, 'La variabilité cardiaque au réveil renseigne surtout sur…', 'mcq', '["la fatigue du système nerveux","la taille du cœur","la souplesse","la vitesse maximale"]'::jsonb, 0, 'Elle reflète l’état de récupération : une variabilité basse peut signaler de la fatigue.', 12),
    ('9c07c1b4-a535-5749-a1d6-de31e100d700'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Quelles hormones sont libérées face à un enjeu stressant ?', 'mcq', '["L’adrénaline et le cortisol","L’insuline et la leptine","La mélatonine et la thyroxine","Le calcium et le fer"]'::jsonb, 0, 'Adrénaline et cortisol mobilisent le corps : cœur plus rapide, muscles tendus.', 1),
    ('437f4e55-8820-59d4-9b6f-754a5fe66d12'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Que dit la courbe de Yerkes-Dodson ?', 'mcq', '["La performance est maximale à un niveau d’activation intermédiaire","Plus on est stressé, mieux on performe","Le stress n’a aucun effet","La performance baisse toujours avec l’activation"]'::jsonb, 0, 'La courbe est en U inversé : trop peu ou trop d’activation dégrade la performance.', 2),
    ('3811bede-05b3-52d6-b04d-54e6c96c057a'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Combien de respirations par minute vise la cohérence cardiaque ?', 'mcq', '["Environ 6","Environ 20","Environ 40","Environ 2"]'::jsonb, 0, 'On respire environ 6 fois par minute, pendant 5 minutes, en inspirant puis expirant 5 secondes.', 3),
    ('b2b1e389-ab65-5255-aae7-13bb982b772e'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Combien de temps dure en général une séance de cohérence cardiaque ?', 'mcq', '["5 minutes","10 secondes","2 heures","1 jour"]'::jsonb, 0, 'Cinq minutes à six respirations par minute suffisent pour apaiser le rythme du cœur.', 4),
    ('c4523c73-cec3-5bb1-807a-0934df5f2c9a'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Que fait un athlète avec une routine d’avant-performance ?', 'mcq', '["Il répète les mêmes gestes pour ancrer son attention","Il évite de penser à son sport","Il change de rituel à chaque fois","Il saute l’échauffement"]'::jsonb, 0, 'Comme Nadal avant un service, la routine stabilise l’attention et limite les pensées parasites.', 5),
    ('23f67de3-43c4-5fac-9ca3-f2724011334e'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Qu’est-ce que l’imagerie mentale ?', 'mcq', '["Se voir réussir en pensée, en détail","Regarder des photos de son adversaire","Dessiner son équipement","Comparer ses résultats"]'::jsonb, 0, 'On visualise l’action du début à la fin, comme Michael Phelps le faisait pour ses courses.', 6),
    ('bb43f404-aa23-51b0-9021-fa5330504ad3'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Lequel est un objectif de processus ?', 'mcq', '["Garder le dos droit pendant la course","Gagner la médaille d’or","Battre le record du monde","Finir devant son rival"]'::jsonb, 0, 'Un objectif de processus dépend de toi ; un objectif de résultat dépend aussi des autres.', 7),
    ('a2cc2866-fcc0-5c19-b53e-66ffaef1cb40'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Que signifie le « T » de SMART ?', 'mcq', '["Défini dans le Temps","Très difficile","Technique","Toujours gagnant"]'::jsonb, 0, 'Un objectif SMART a une échéance : Spécifique, Mesurable, Atteignable, Réaliste, Temporel.', 8),
    ('ad51b808-3a33-5bcc-b5db-52a5d4a97fa8'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Le stress est toujours mauvais pour la performance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un stress modéré mobilise ; il nuit seulement s’il est trop faible ou trop fort.', 9),
    ('5c60d2aa-f589-5883-90a7-7fa0a94ed589'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Le « choke » désigne…', 'mcq', '["une contre-performance sous pression","un type d’échauffement","une technique de respiration","un exercice de force"]'::jsonb, 0, 'On surveille son geste au lieu de lui faire confiance, et la performance s’effondre.', 10),
    ('e5e24985-f1c8-5dc3-b03d-a7c041459915'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Pourquoi Simone Biles s’est-elle retirée de plusieurs finales aux Jeux de Tokyo en 2021 ?', 'mcq', '["Pour protéger sa santé mentale","Parce qu’elle était blessée au genou","Parce qu’elle avait perdu ses qualifications","Parce que le règlement l’exigeait"]'::jsonb, 0, 'Son geste a ouvert un débat sur la santé mentale des athlètes.', 11),
    ('0ee8ee15-0137-551e-b962-bd65c6ed764f'::uuid, '97a25c2c-61c5-5350-9b88-6b4b8b832e86'::uuid, 'Les outils du mental peuvent aussi servir pour le Grand oral.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le Grand oral est une performance sous enjeu : souffle, routine et imagerie s’y appliquent.', 12),
    ('ab92063e-748b-5899-b3fe-6d1f24580418'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Quelle est la durée typique de la fatigue en cas de surentraînement ?', 'mcq', '["Des semaines, voire des mois","Quelques minutes","Une demi-journée","Une seule nuit"]'::jsonb, 0, 'Le surentraînement est un déséquilibre durable, contrairement à la fatigue normale qui disparaît après un bon repos.', 1),
    ('9ec72567-dfe7-585e-816c-ef6c3c0ed791'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Lequel de ces signes peut alerter sur un surentraînement ?', 'mcq', '["Une FC de repos élevée au réveil","Une envie de manger plus de fruits","Un meilleur sommeil","Une forme meilleure chaque semaine"]'::jsonb, 0, 'Une FC de repos qui monte, avec une performance qui baisse, est un signal classique.', 2),
    ('656bdc7e-cae1-50aa-9c92-8040e626622c'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Qu’est-ce qui peut causer un surentraînement ?', 'mcq', '["Une charge qui monte trop vite sans décharge","Une semaine de repos complet","Un bon sommeil","Des séances variées"]'::jsonb, 0, 'Sans décharge ni récupération, la fatigue s’accumule au lieu de se transformer en progrès.', 3),
    ('9ece531c-ae9a-5387-9e3d-0ed999b77480'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'On progresse surtout pendant l’effort, pas pendant le repos.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’effort lance le signal ; c’est la récupération qui fabrique le progrès.', 4),
    ('d740c438-6c7e-5a05-b21a-3c3675319b50'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Quelle durée de sommeil recommande-t-on à un athlète adolescent ?', 'mcq', '["9 heures ou plus","4 heures","6 heures","Peu importe"]'::jsonb, 0, 'Le sommeil est le premier levier de récupération, et un athlète adolescent en a besoin d’au moins 9 heures.', 5),
    ('208216bf-5751-5299-881c-da35fa83beb9'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Que montre l’étude de Stanford sur des basketteurs ?', 'mcq', '["Dormir environ 10 heures améliore sprints et lancers francs","Dormir moins améliore la vitesse","Le sommeil n’a aucun effet","Les lancers francs empirent après une nuit longue"]'::jsonb, 0, 'Les joueurs qui dormaient environ 10 heures ont amélioré leurs sprints et leurs lancers francs.', 6),
    ('cba69f09-5872-556f-a969-45de2d20751b'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Que fait un bain froid pris systématiquement après chaque séance de musculation ?', 'mcq', '["Il soulage mais peut freiner la prise de muscle","Il double la prise de muscle","Il supprime tout besoin de sommeil","Il remplace l’échauffement"]'::jsonb, 0, 'Le bain froid calme la douleur, mais le prendre à chaque fois peut atténuer le signal d’adaptation.', 7),
    ('be2e4703-6a4f-5afd-840e-3d4398bc4e29'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Le massage et la compression ont un effet…', 'mcq', '["modeste, surtout de confort","décisif sur la performance","dangereux pour le cœur","identique à une nuit de sommeil"]'::jsonb, 0, 'Leur effet est modeste : ils aident à se sentir mieux sans remplacer sommeil et nutrition.', 8),
    ('fc79e650-283d-5b49-a878-a72c50530698'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Comment prévient-on le surentraînement ?', 'mcq', '["Par la planification et un carnet qui permet d’alléger à temps","En ajoutant une séance par semaine","En supprimant tous les repos","En s’entraînant à jeun"]'::jsonb, 0, 'Des décharges prévues et un carnet qui alerte sur les signaux évitent d’arriver au bout du rouleau.', 9),
    ('8e36d9c5-9218-52de-a160-96626054b372'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Pourquoi éviter les écrans juste avant de dormir ?', 'mcq', '["Leur lumière retarde l’endormissement","Ils fatiguent les muscles","Ils font grossir","Ils empêchent la digestion"]'::jsonb, 0, 'Moins de sommeil de qualité, c’est moins de récupération.', 10),
    ('aeb882f9-4e5b-58d7-a999-78d6b4079b63'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Le stress scolaire peut contribuer au surentraînement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le corps additionne toutes les fatigues : examens, sommeil écourté et séances de sport.', 11),
    ('d54cceb7-1648-505c-96cc-2799a8587f58'::uuid, 'b7d4f7ab-1658-56f4-a9a2-3698db153d9e'::uuid, 'Léo voit ses chronos reculer et ajoute une séance. Quelle est la meilleure réaction ?', 'mcq', '["Alléger, dormir davantage et en parler","Ajouter encore des séances","Supprimer l’échauffement","Ne plus manger de glucides"]'::jsonb, 0, 'Une performance qui baisse malgré le travail doit faire lever le pied, pas en rajouter.', 12),
    ('ebe01f9b-71cb-53a9-ac3d-b16eca78f5c0'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Combien de minutes par jour l’OMS recommande-t-elle aux 5-17 ans ?', 'mcq', '["60 minutes","10 minutes","5 minutes","3 heures"]'::jsonb, 0, 'L’OMS recommande 60 minutes d’activité modérée à soutenue chaque jour pour les jeunes.', 1),
    ('589efabe-bb49-5f74-8834-22e919da8041'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Quelle recommandation hebdomadaire vaut pour les adultes ?', 'mcq', '["150 à 300 minutes","15 minutes","600 minutes","Aucune"]'::jsonb, 0, 'L’OMS vise 150 à 300 minutes d’activité modérée par semaine chez l’adulte.', 2),
    ('999e42f1-fd4d-5b76-88a2-a71b6517c872'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Que désigne la sédentarité ?', 'mcq', '["Le temps passé assis ou allongé éveillé","Le fait de pratiquer un sport de salon","Le manque de sommeil","Une maladie du cœur"]'::jsonb, 0, 'La sédentarité, c’est le temps passé assis ; elle se distingue de l’inactivité physique.', 3),
    ('718f3781-f49e-5752-8c65-22419038f9a6'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Faire une heure de sport suffit à annuler les effets d’une journée entière passée assise.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sédentarité et inactivité sont deux risques distincts : on peut faire du sport et rester trop assis le reste du temps.', 4),
    ('56b02a27-1b2c-50e1-b628-d5e49956a432'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Selon l’ANSES (2020), quelle part des 11-17 ans présente un risque sanitaire préoccupant en France ?', 'mcq', '["Deux tiers","Un sur dix","Aucun","Tous"]'::jsonb, 0, 'Trop d’écrans et pas assez d’activité : deux tiers des 11-17 ans sont concernés.', 5),
    ('c9b4fda0-4a1f-5597-8696-557854bbdd2e'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Que permet la loi de 2016, en vigueur en 2017 ?', 'mcq', '["Qu’un médecin prescrive de l’activité physique adaptée","D’interdire le sport aux malades","De supprimer l’EPS","De financer les Jeux"]'::jsonb, 0, 'C’est le « sport sur ordonnance » : l’activité physique adaptée devient une prescription médicale.', 6),
    ('d6c7dcf9-d83d-5956-8793-2ed1865b89fb'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Que sont les Maisons Sport-Santé, créées à partir de 2019 ?', 'mcq', '["Des lieux qui accompagnent le retour à la pratique sportive","Des hôpitaux de sport","Des clubs de haut niveau","Des écoles spécialisées"]'::jsonb, 0, 'Elles orientent et conseillent ceux qui veulent se remettre à l’activité physique, avec un suivi.', 7),
    ('e470962d-a370-57aa-94dc-31da38e9b908'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Depuis 2022, que prévoit l’école primaire en matière d’activité physique ?', 'mcq', '["30 minutes d’activité physique quotidienne","Une heure de sport par mois","La suppression de la récréation","Un examen de sport"]'::jsonb, 0, 'Les 30 minutes quotidiennes visent à faire du mouvement un réflexe dès le plus jeune âge.', 8),
    ('0d6a381c-65f4-5a35-9dcd-4a7936976821'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Quelle année a vu l’activité physique déclarée grande cause nationale ?', 'mcq', '["2024","1995","2030","1968"]'::jsonb, 0, 'En 2024, année des Jeux de Paris, l’activité physique a été déclarée grande cause nationale.', 9),
    ('42dbf311-db5d-577b-bb2b-2d7f0bce30bf'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Où l’OMS classe-t-elle l’inactivité physique parmi les facteurs de risque de mortalité ?', 'mcq', '["Parmi les premiers","Tout en bas","Elle ne la classe pas","Après la météo"]'::jsonb, 0, 'L’inactivité physique figure parmi les premiers facteurs de risque de mortalité dans le monde.', 10),
    ('dec64a40-f907-5558-a10f-845b77beab5a'::uuid, '0ea92ee2-32b4-5270-b062-e4adc34c42fd'::uuid, 'Le sport sur ordonnance, c’est de l’activité physique adaptée à l’état de santé de chacun.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’activité est dosée et encadrée pour permettre de progresser sans danger.', 11),
    ('49e83dc9-ea63-5c3a-97ab-2f09ad237a6e'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Quel sociologue parle d’un « processus de civilisation » où le sport canalise la violence ?', 'mcq', '["Norbert Elias","Pierre Bourdieu","Émile Durkheim","Pierre de Coubertin"]'::jsonb, 0, 'Elias montre que la violence est peu à peu contrôlée, le sport en étant une forme réglementée.', 1),
    ('3c90f275-8edb-544d-8315-7e797d5188f2'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'En quelle année Pierre Bourdieu a-t-il publié son analyse des sports et des classes sociales ?', 'mcq', '["1978","1898","1948","2008"]'::jsonb, 0, 'En 1978, il a montré que les pratiques sportives varient selon l’origine sociale.', 2),
    ('f13abe71-02c3-5f28-b2b7-54f7d051a3ce'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Selon Bourdieu, quels sports sont plutôt associés aux classes aisées ?', 'mcq', '["Golf, tennis, équitation","Boxe, football","Lutte, pétanque","Aucun sport"]'::jsonb, 0, 'Golf, tennis et équitation sont classiquement associés aux classes aisées, boxe et football aux classes populaires.', 3),
    ('9f64fb06-a0f3-5a0b-a385-6cddc3d20971'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Le haka est…', 'mcq', '["une danse rituelle des All Blacks avant les matchs","un type de ballon","une règle de hors-jeu","un trophée"]'::jsonb, 0, 'Le haka des All Blacks néo-zélandais est un signe d’identité collective.', 4),
    ('1ec2f0eb-5fb2-599f-8b6f-7ce7f4ee97aa'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Que représentent les deux étoiles sur le maillot des Bleus ?', 'mcq', '["Les deux titres de champion du monde (1998 et 2018)","Deux Jeux olympiques","Deux Coupes d’Europe","Deux sélectionneurs"]'::jsonb, 0, 'Elles rappellent les deux victoires en Coupe du monde, en 1998 et en 2018.', 5),
    ('8d155491-4285-599b-84d9-2ce604c98f39'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Quels drames de stade ont marqué 1985 et 1989 ?', 'mcq', '["Heysel et Hillsborough","Wembley et Maracanã","Roland-Garros et Bercy","Munich et Montréal"]'::jsonb, 0, 'Le Heysel (1985) et Hillsborough (1989) ont poussé à renforcer la sécurité des stades.', 6),
    ('9041c511-1b12-56ec-9766-22b9d4fe0654'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'D’où sont nés les Jeux paralympiques ?', 'mcq', '["De la compétition de Stoke Mandeville en 1948","D’un congrès à Paris en 1900","Des Jeux de Rome en 1896","D’un match de rugby en 1920"]'::jsonb, 0, 'Elle réunissait des blessés de guerre ; la première édition officielle a eu lieu à Rome en 1960.', 7),
    ('09e157a3-70cd-55ca-be1d-69aae68b83dd'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Où a eu lieu la première édition officielle des Jeux paralympiques ?', 'mcq', '["À Rome, en 1960","À Paris, en 1924","À Londres, en 1908","À Tokyo, en 2021"]'::jsonb, 0, 'Rome a accueilli les premiers Jeux paralympiques officiels en 1960.', 8),
    ('4602aee5-5522-5e12-8ddb-b9d8359a7c75'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Le sport reste étranger aux débats politiques et sociaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Laïcité, égalité femmes-hommes, environnement, violence : le sport est au cœur de nombreux débats.', 9),
    ('216cd048-599a-5ac8-89af-26e9e7eb7311'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Le dopage peut être vu comme un symptôme de…', 'mcq', '["la pression à gagner","la baisse du nombre de pratiquants","la fermeture des stades","l’absence d’arbitres"]'::jsonb, 0, 'Quand l’enjeu devient énorme, certains sont tentés de tricher : le dopage révèle cette pression.', 10),
    ('47f15e31-8d59-58c6-86b6-6ccce79936e2'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Les sociologues étudient le sport comme institution, économie et discours.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Fédérations et règles, argent et médias, valeurs attribuées au sport : trois façons de le lire.', 11),
    ('31164bed-9d62-5347-8675-87daba4993a2'::uuid, '4e44d3c1-db3d-5a15-8513-0c247d21c091'::uuid, 'Quel est l’impact environnemental évoqué dans le sport ?', 'mcq', '["La neige artificielle et les déplacements","Le bruit des chaussures","La couleur des maillots","Le nombre de spectateurs"]'::jsonb, 0, 'Produire de la neige artificielle et multiplier les voyages laisse une empreinte écologique.', 12),
    ('9bdbf3bf-a01c-5689-a756-89b01c083d4c'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Quelles sont les trois valeurs olympiques ?', 'mcq', '["Excellence, amitié, respect","Force, vitesse, endurance","Gloire, argent, victoire","Patrie, honneur, courage"]'::jsonb, 0, 'La Charte olympique place l’excellence, l’amitié et le respect au cœur du mouvement.', 1),
    ('82255ea6-ee8f-51b1-a240-5f9e4aa832ad'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Que demande la trêve olympique ?', 'mcq', '["Suspendre les conflits pendant les Jeux","Arrêter le championnat de football","Supprimer les médailles","Interdire les spectateurs"]'::jsonb, 0, 'Appuyée par une résolution de l’ONU, la trêve invite à suspendre les conflits pendant les Jeux.', 2),
    ('f20a5d7c-be7d-595e-aa41-853efa9a4292'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Quel est l’objectif de l’Agenda 2020 du CIO ?', 'mcq', '["Des Jeux moins chers qui réutilisent des sites existants","Construire plus de stades neufs","Doubler le nombre d’épreuves","Supprimer les Jeux d’hiver"]'::jsonb, 0, 'Face aux coûts, le CIO a voulu limiter les constructions nouvelles.', 3),
    ('7041e338-4bb5-58b3-80a9-156caf514a32'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Quelle part approximative des sites de Paris 2024 était existante ou temporaire ?', 'mcq', '["95 %","10 %","50 %","0 %"]'::jsonb, 0, 'Environ 95 % des sites étaient existants ou temporaires, ce qui limitait les constructions.', 4),
    ('9ac3c352-03a3-5213-aadf-b24f2b38eca3'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Combien d’athlètes ont participé à Paris 2024 environ ?', 'mcq', '["10 500","500","2 000","50 000"]'::jsonb, 0, 'Environ 10 500 athlètes ont pris part aux Jeux, à parité entre femmes et hommes.', 5),
    ('eee72176-0830-58b4-8ab9-8242d733965a'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Que montre la billetterie paralympique de Paris 2024 ?', 'mcq', '["Un record de ventes","Un échec complet","Aucune vente","Une gratuité"]'::jsonb, 0, 'La billetterie paralympique a battu un record.', 6),
    ('742c3aa4-501f-59d3-a897-3e362485038d'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Où le village olympique est-il devenu un quartier de logements ?', 'mcq', '["À Saint-Denis, Saint-Ouen et L’Île-Saint-Denis","À Marseille","À Bordeaux","À Lille"]'::jsonb, 0, 'Le village a été conçu pour devenir un quartier après les Jeux.', 7),
    ('e9f2e5b3-c375-594a-9060-7943fe9c1a2b'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Qu’est-ce qui a été rendu à la baignade en 2025 ?', 'mcq', '["La Seine","Le canal du Midi","Le Rhin","La Loire"]'::jsonb, 0, 'Après de lourds travaux, la baignade dans la Seine est de nouveau possible.', 8),
    ('846c85ac-f87c-5c83-8a11-6249b6fbed5f'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Les Jeux olympiques ne suscitent jamais aucune critique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Coût, sécurité et délogements ont suscité des controverses autour de Paris 2024.', 9),
    ('5aa23d17-1ab8-57bd-993d-0b27765ed88a'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Quelle ville accueillera les Jeux d’été de 2028 ?', 'mcq', '["Los Angeles","Londres","Tokyo","Sydney"]'::jsonb, 0, 'Los Angeles organise les Jeux d’été de 2028.', 10),
    ('2ad208ed-b2c1-500d-90d3-ba84ffc6fdbc'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Les Jeux d’hiver de 2030 sont prévus dans les Alpes françaises.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après Milan-Cortina en 2026, les Alpes françaises sont les hôtes de 2030.', 11),
    ('9ce137bf-4f81-5681-9139-f03f2c63b19e'::uuid, '95f6cdc5-be30-5ffc-aac5-43d6e11bd722'::uuid, 'Pourquoi dit-on qu’un bon héritage se prépare avant les Jeux ?', 'mcq', '["Parce qu’on ne construit que ce dont on se servira ensuite","Parce que les Jeux sont gratuits","Parce qu’il faut éviter tout spectateur","Parce que l’héritage est toujours automatique"]'::jsonb, 0, 'Penser l’usage après l’événement évite les équipements inutiles et coûteux.', 12),
    ('58293b98-9456-54f8-936a-265456905224'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Que signifie STAPS ?', 'mcq', '["Sciences et techniques des activités physiques et sportives","Sport, théâtre, arts, philosophie et santé","Stages techniques d’athlétisme et de sport","Sciences, technologies, arts, pratique et sport"]'::jsonb, 0, 'STAPS regroupe les formations universitaires consacrées aux activités physiques et sportives.', 1),
    ('62c02a10-4cfb-5ca7-9244-2f7f9875c93c'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Combien de mentions compte la licence STAPS ?', 'mcq', '["Cinq","Deux","Douze","Une seule"]'::jsonb, 0, 'Entraînement, activité physique adaptée et santé, éducation et motricité, management, ergonomie : cinq mentions.', 2),
    ('c2b90959-7fed-5a97-b289-fff74ca2c2b5'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Quelle mention convient à qui veut gérer un club ou un événement ?', 'mcq', '["Management du sport","Entraînement sportif","Éducation et motricité","Ergonomie du sport"]'::jsonb, 0, 'Management du sport forme aux métiers de la gestion des structures et événements.', 3),
    ('c5c43eed-a6e5-55ed-bc8b-df6afc213d84'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Quels trois champs les attentes Parcoursup pour STAPS mettent-elles en avant ?', 'mcq', '["Sciences, expression, pratique","Chant, cuisine, dessin","Droit, commerce, langues","Danse, théâtre, musique"]'::jsonb, 0, 'Il faut des bases scientifiques, savoir s’exprimer et avoir une pratique sportive.', 4),
    ('dce316b1-17a4-5cb7-b38a-24a9d0c8db0a'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Par quel concours devient-on professeur d’EPS ?', 'mcq', '["Le CAPEPS","Le BAFA","Le brevet","Le permis"]'::jsonb, 0, 'Après un master MEEF, le CAPEPS ouvre l’accès au métier d’enseignant d’EPS.', 5),
    ('8165edaf-028f-5073-9afb-6d52ff498920'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Quel diplôme du ministère des Sports permet notamment d’animer et d’entraîner, avant le DEJEPS ?', 'mcq', '["Le BPJEPS","Le DESJEPS","Le CAP","Le DUT"]'::jsonb, 0, 'Le BPJEPS précède le DEJEPS puis le DESJEPS dans les diplômes pour animer, entraîner et diriger.', 6),
    ('49ce4aca-9b47-5725-8035-e459e2106b60'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'L’accès aux études de kinésithérapie est identique partout.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Selon les universités, on passe par PASS, LAS ou parfois une première année de STAPS : il faut vérifier auprès de l’établissement.', 7),
    ('67d8e700-0263-5c22-b4e4-4ba75147de0f'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Que fait un analyste de données dans le sport ?', 'mcq', '["Il exploite les chiffres pour éclairer les décisions de l’entraîneur","Il arbitre les matchs","Il soigne les blessés","Il fabrique les ballons"]'::jsonb, 0, 'GPS, capteurs et statistiques sont analysés pour guider l’entraînement.', 8),
    ('d0596300-512f-5f27-8fa8-113ab52e806f'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Que peut obtenir un jeune sportif de haut niveau pour ses études ?', 'mcq', '["Des aménagements scolaires","Une dispense de bac","La suppression des examens","Un diplôme automatique"]'::jsonb, 0, 'Horaires, examens, soutien : on adapte la scolarité sans la sacrifier.', 9),
    ('12165520-2a73-56bc-bf62-2c54e3ec77e6'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Le sport représente en France…', 'mcq', '["plusieurs centaines de milliers d’emplois","moins de cent emplois","aucun emploi","seulement des bénévoles"]'::jsonb, 0, 'Enseignement, clubs, événementiel, industrie, médias : le secteur emploie beaucoup de monde.', 10),
    ('2ef3a015-a7d7-519f-87c7-1e11c76c0226'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Pour travailler dans le sport, il faut forcément être champion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il existe de nombreux métiers autour du sport, du management à la santé en passant par l’industrie.', 11),
    ('7d1fe686-91f4-568c-b967-6b7f93411c4d'::uuid, '887ac0a3-be32-5419-a1f5-9d9502d0cd11'::uuid, 'Quelle bonne méthode pour choisir sa formation ?', 'mcq', '["Partir du métier qui attire puis remonter vers la formation","Choisir au hasard","Suivre uniquement ses amis","Ignorer les conditions d’accès"]'::jsonb, 0, 'Chaque métier a son diplôme : on identifie d’abord ce qu’on veut faire.', 12),
    ('6370d58d-cd23-5b4d-b9cc-c6d22dd8e8e1'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Combien d’épreuves compte le contrôle en cours de formation d’EPS au bac ?', 'mcq', '["Une","Deux","Trois","Cinq"]'::jsonb, 2, 'Trois épreuves, sur trois activités distinctes.', 1),
    ('6736ccca-9900-5ad6-9442-51d76a23ae88'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Les trois épreuves doivent relever…', 'mcq', '["Du même champ d’apprentissage","De trois champs d’apprentissage différents","Uniquement des sports collectifs","De deux champs au choix"]'::jsonb, 1, 'C’est une obligation fixée par la note de service.', 2),
    ('a7a1626e-5516-5c3e-bc5c-d192eb3779c7'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Sur combien de points est noté l’AFL1 dans chaque épreuve ?', 'mcq', '["12","8","6","20"]'::jsonb, 0, 'Les AFL2 et AFL3 se partagent les 8 points restants.', 3),
    ('466bd2a6-e190-539b-bb49-317649fcac40'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Laquelle de ces répartitions AFL2 / AFL3 est possible ?', 'mcq', '["8 / 0","5 / 3","0 / 8","6 / 2"]'::jsonb, 3, 'Les trois choix sont 4/4, 6/2 et 2/6.', 4),
    ('7c10cf3d-c4b0-5d1a-97a2-68fcf41b024f'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Quel est le coefficient de l’EPS au baccalauréat ?', 'mcq', '["2","6","10","16"]'::jsonb, 1, 'L’EPS pèse autant qu’une matière importante du tronc commun.', 5),
    ('3cb9523f-b689-5b61-852d-f677d35115a8'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Une absence non justifiée à une épreuve entraîne…', 'mcq', '["Un 0 à cette épreuve, non éliminatoire","L’élimination du bac","Une simple remarque","Le report automatique de l’épreuve"]'::jsonb, 0, 'Elle fait chuter la moyenne des trois épreuves.', 6),
    ('23b6d3b1-623d-534a-9d97-062672e3ea06'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Combien d’activités au moins doivent venir de la liste nationale ?', 'mcq', '["Aucune","Une","Deux","Trois"]'::jsonb, 2, 'La troisième peut venir de la liste académique ou de l’établissement.', 7),
    ('57ef2399-245b-5d17-84f7-78594cf28f4f'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'L’AFL2 et l’AFL3 s’évaluent uniquement le jour de l’épreuve.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils s’évaluent au fil de la séquence et sont finalisés le jour de l’épreuve.', 8),
    ('2cca0130-cacf-5065-8178-1499dce03f26'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Qui évalue les épreuves du CCF ?', 'mcq', '["Un jury extérieur uniquement","L’élève lui-même","Le chef d’établissement seul","Deux enseignants d’EPS, dont celui de la classe"]'::jsonb, 3, 'C’est le principe de la co-évaluation.', 9),
    ('6dc57ef3-38d6-525d-8dbd-ab2baabd9be5'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Un élève obtient 15, 13 et 11. Sa note finale d’EPS vaut…', 'mcq', '["11/20","13/20","15/20","39/20"]'::jsonb, 1, '(15 + 13 + 11) / 3 = 13.', 10),
    ('116a86d3-32f0-517a-bfb7-b7c87ca6fce6'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Un candidat individuel passe l’EPS en examen ponctuel sur deux activités.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le CCF concerne les élèves scolarisés en lycée public ou privé sous contrat.', 11),
    ('1fbd6cb7-6559-54c7-a68d-ab1d33e95cb4'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'En cas de blessure temporaire attestée, que prévoit l’établissement ?', 'mcq', '["Un 0 automatique","Une dispense définitive de l’EPS","Une épreuve adaptée ou différée","Rien du tout"]'::jsonb, 2, 'La blessure doit être authentifiée par l’autorité médicale scolaire.', 12),
    ('59a7d3c2-609e-5690-933d-2943be30487a'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Combien d’heures par semaine compte l’enseignement optionnel d’EPS ?', 'mcq', '["3 heures","1 heure","10 heures","30 minutes"]'::jsonb, 0, 'L’option EPS représente 3 heures par semaine, de la 2de à la Tle.', 1),
    ('96557678-3bb2-5e18-85fb-5c567a9b9f23'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Comment l’option EPS est-elle évaluée au bac ?', 'mcq', '["En contrôle continu","Par un oral final uniquement","Elle n’est pas évaluée","Par un écrit de quatre heures"]'::jsonb, 0, 'L’option EPS compte en contrôle continu.', 2),
    ('8131bcdf-5229-5498-9c85-449715065c73'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'En quelle année a été créée la spécialité EPPCS ?', 'mcq', '["2021","1998","2005","2030"]'::jsonb, 0, 'La spécialité « Éducation physique, pratiques et culture sportives » date de 2021.', 3),
    ('6b08f335-18dc-57a9-8300-4dddb6792651'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Que signifie EPPCS ?', 'mcq', '["Éducation physique, pratiques et culture sportives","Éducation populaire pour les clubs sportifs","Entraînement, performance, préparation et compétition sportive","Équipement physique, pédagogie et conseil sportif"]'::jsonb, 0, 'EPPCS désigne la spécialité mêlant pratique et culture du sport.', 4),
    ('02d28419-de15-5b95-9f67-31d7b3deb216'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Combien d’heures par semaine compte l’EPPCS en terminale ?', 'mcq', '["6 heures","1 heure","20 heures","2 heures"]'::jsonb, 0, 'La spécialité compte 4 heures en 1re et 6 heures en Tle.', 5),
    ('5e30f23d-1398-5f39-9206-8d2be4872f87'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Que comprend l’épreuve terminale d’EPPCS ?', 'mcq', '["Un écrit et une partie pratique","Un écrit seulement","Un oral seulement","Aucune épreuve"]'::jsonb, 0, 'Elle associe un écrit et une partie pratique.', 6),
    ('ed8f55b7-de39-5353-a95e-66b4baa9b616'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Que trouve-t-on dans le programme de l’EPPCS ?', 'mcq', '["Sciences du sport, histoire, sociologie, projet collectif","Uniquement du football","Seulement des règles","Rien de théorique"]'::jsonb, 0, 'L’EPPCS mêle pratique, culture et réflexion : sciences, histoire, sociologie et projet.', 7),
    ('a01538fe-2070-55b1-b446-96a4a85f791f'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'L’EPPCS est un cours de sport supplémentaire sans aucun écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y a de l’écrit et des notions à maîtriser, comme dans une matière théorique.', 8),
    ('7d705fdf-5ba2-522b-9e56-966f5b2e541b'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'À quelles études l’EPPCS peut-elle préparer ?', 'mcq', '["STAPS, kinésithérapie, éducation, management du sport","Uniquement la médecine","Uniquement le droit","Aucune étude"]'::jsonb, 0, 'Elle s’adresse souvent à ceux qui visent un métier lié au sport.', 9),
    ('0d1dccce-7075-5264-a4cb-2103685e59e7'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Que permettent les sections sportives scolaires ?', 'mcq', '["S’entraîner davantage pendant la scolarité","Supprimer les cours","Quitter le lycée","Éviter les examens"]'::jsonb, 0, 'Elles proposent plus d’entraînement sur le temps scolaire.', 10),
    ('5b887492-ef5f-5e6d-927f-1a78c6c4b2f4'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Les pôles espoirs accueillent des jeunes à fort potentiel sportif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils réunissent des jeunes prometteurs avec un entraînement structuré et une scolarité adaptée.', 11),
    ('a8d54b14-00b4-51cb-9510-512fe52c8006'::uuid, '29e77ab0-c026-51b9-a02b-cadf0765e403'::uuid, 'Comment l’EPPCS peut-elle aider pour le Grand oral ?', 'mcq', '["Elle fournit des sujets sportifs solides, comme la récupération ou l’olympisme","Elle dispense de le passer","Elle impose le sujet","Elle supprime le jury"]'::jsonb, 0, 'Les notions travaillées servent de terrain pour construire un Grand oral argumenté.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('sport');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('sport')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 568 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 568 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
